import{c as s,S as e,j as t,m as i}from"./chunks/framework.VsSDrsS3.js";const h=JSON.parse('{"title":"IaaS / PaaS / SaaS","description":"","frontmatter":{},"headers":[],"relativePath":"knowledge/architecture/iaas-paas-saas.md","filePath":"knowledge/architecture/iaas-paas-saas.md","lastUpdated":1780046787000}'),r={name:"knowledge/architecture/iaas-paas-saas.md"};function S(l,a,n,o,c,d){return e(),t("div",null,[...a[0]||(a[0]=[i('<h1 id="iaas-paas-saas" tabindex="-1">IaaS / PaaS / SaaS <a class="header-anchor" href="#iaas-paas-saas" aria-label="Permalink to “IaaS / PaaS / SaaS”">​</a></h1><h2 id="最简单的区分" tabindex="-1">最简单的区分 <a class="header-anchor" href="#最简单的区分" aria-label="Permalink to “最简单的区分”">​</a></h2><ul><li><strong>IaaS（基础设施即服务）：</strong> 给你一台装好系统的服务器，你自己装环境、部署应用（如 AWS EC2）</li><li><strong>PaaS（平台即服务）：</strong> 给你一个运行环境，你只管推代码，不用管服务器（如 Vercel、Heroku）</li><li><strong>SaaS（软件即服务）：</strong> 给你一个直接可用的软件，啥都不用管（如飞书、Notion、GitHub）</li></ul><p>类比：IaaS 是租厨房（自己做菜），PaaS 是叫外卖（只点菜），SaaS 是去餐厅（吃现成的）。</p><h2 id="iaas-vs-paas-vs-saas-选择策略" tabindex="-1">IaaS vs PaaS vs SaaS 选择策略 <a class="header-anchor" href="#iaas-vs-paas-vs-saas-选择策略" aria-label="Permalink to “IaaS vs PaaS vs SaaS 选择策略”">​</a></h2><ul><li>自建项目/需要完全控制 → IaaS（AWS EC2 / 阿里云 ECS）</li><li>快速部署前端应用 → PaaS（Vercel / Netlify）</li><li>想省运维成本 → SaaS（直接用现成的服务）</li></ul><p>常见的演变路径：创业初期用 SaaS（省钱省人）→ 规模上来后转 PaaS（需要定制）→ 特别大了自己搞 IaaS（成本最优）。</p>',7)])])}const _=s(r,[["render",S]]);export{h as __pageData,_ as default};
